class A {
    A() { System.out.print("A"); }
}
class B extends A {
    B() { System.out.print("B"); }
}
public class Test {
    public static void main(String[] args) {
        new B();
    }
}

class Parent {
    public void print() { System.out.print("P"); }
}
class Child extends Parent {
    @Override
    public void print(int x) { System.out.print("C" + x); }
}
public class Test {
    public static void main(String[] args) {
        new Child().print(1);
    }
}

class Employee {
    @Override
    public String toString() { return "Emp"; }
}
class Manager extends Employee { }
public class Test {
    public static void main(String[] args) {
        System.out.print(new Manager());
    }
}

class Base {
    private int id = 10;
}
class Derived extends Base {
    public void show() { System.out.print(id); }
}
public class Test {
    public static void main(String[] args) {
        new Derived().show();
    }
}

class X {
    X(int i) { System.out.print("X" + i); }
}
class Y extends X {
    Y() {
        super(5);
        System.out.print("Y");
    }
}
public class Test {
    public static void main(String[] args) {
        new Y();
    }
}

class Machine {
    public void start(double power) { System.out.print("M" + power); }
}
class Generator extends Machine {
    public void start(int power) { System.out.print("G" + power); }
}
public class Test {
    public static void main(String[] args) {
        Machine m = new Generator();
        m.start(10);
    }
}

class Item {
    int val;
    Item(int v) { val = v; }
}
public class Test {
    public static void main(String[] args) {
        Item[] arr1 = { new Item(1) };
        Item[] arr2 = arr1.clone();
        arr2[0].val = 2;
        System.out.print(arr1[0].val);
    }
}

class Vehicle {
    public void start() { System.out.print("V"); }
}
class Car extends Vehicle {
    @Override
    protected void start() { System.out.print("C"); }
}
public class Test {
    public static void main(String[] args) {
        Vehicle v = new Car();
        v.start();
    }
}

class Part {
    protected int id;
    public Part(int id) { this.id = id; }
}
class Engine extends Part {
    private int id = 5;
    public Engine() {
        System.out.print(this.id);
    }
}
public class Test {
    public static void main(String[] args) {
        new Engine();
    }
}

class Data {
    @Override
    public String toString() {
        return "Data-" + super.toString();
    }
}
class SubData extends Data {
    @Override
    public String toString() {
        return "Sub-" + this.toString();
    }
}
public class Test {
    public static void main(String[] args) {
        System.out.print(new SubData().toString());
    }
}
